diff --git a/apps/hyper/HyperKCore-Efficient.C b/apps/hyper/HyperKCore-Efficient.C
index e6e3582..48a069c 100644
--- a/apps/hyper/HyperKCore-Efficient.C
+++ b/apps/hyper/HyperKCore-Efficient.C
@@ -1,13 +1,613 @@
+#include <cstdint>
 #define HYPER 1
 #include "hygra.h"
 #include "index_map.h"
 #include "bucket.h"
 #include "edgeMapReduce.h"
+// Hypergraph k-core by direction-optimizing parallel peeling.
+//
+// Level k removes every remaining vertex whose live degree is <= k (core = k);
+// a hyperedge dies with its first removed member. A level runs in rounds over
+// a frontier (vertices leaving at level k):
+//   push: each live hyperedge touching the frontier is processed by its
+//         lowest-numbered frontier member, which decrements the other members.
+//   pull: frontier vertices mark their hyperedges dead; every remaining vertex
+//         recounts its live hyperedges. Cheaper when the frontier is huge.
+//   fix:  few vertices remain: recount them alone, judging a hyperedge live
+//         when all its members are, until none drops. Finishes the level.
+// When the frontier holds every remaining vertex they all take core k.
+//
+// Threads own 64-aligned blocks of vertices and of dead-hyperedge bitmap
+// words; push rounds route kills and decrements to owners as messages, so no
+// atomics touch the hot arrays. deg[] doubles as the result: removed vertices
+// hold their core number, the others their exact live degree.
+#include <climits>
+#include <cstdint>
+#include <cstdlib>
+#include <cstring>
+#include <type_traits>
+#include <utility>
+#ifdef _OPENMP
+#include <omp.h>
+#endif
+
+namespace hkcore {
+#ifndef HKC_W_PUSH_PAR
+#define HKC_W_PUSH_PAR 6.5
+#endif
+#ifndef HKC_W_PUSH_SEQ
+#define HKC_W_PUSH_SEQ 4.0
+#endif
+#ifndef HKC_W_FIX
+#define HKC_W_FIX 2.0
+#endif
+
+typedef uintE vid;  // vertex id; 32-bit unless the substrate is built with EDGELONG
+typedef uint64_t word;
+#define HKC_PF(p) __builtin_prefetch((const void*)(p), 0, 3)
+
+enum { MAXT = 256 };
+
+template <class vertex>
+struct VertexAccess {
+  vertex* V; vertex* H;
+  inline const uintE* vlist(size_t v) const { return V[v].getOutNeighbors(); }
+  inline size_t vdeg(size_t v) const { return V[v].getOutDegree(); }
+  inline const uintE* hlist(size_t e) const { return H[e].getOutNeighbors(); }
+  inline size_t hdeg(size_t e) const { return H[e].getOutDegree(); }
+  inline void prefetch_v(size_t v) const { HKC_PF(&V[v]); }
+  inline void prefetch_vlist(size_t v) const { HKC_PF(V[v].getOutNeighbors()); }
+  inline void prefetch_h(size_t e) const { HKC_PF(&H[e]); }
+};
+
+struct CSRAccess {
+  const uintT* voff; const uintE* vadj; const uintT* hoff; const uintE* hadj;
+  inline const uintE* vlist(size_t v) const { return vadj + voff[v]; }
+  inline size_t vdeg(size_t v) const { return voff[v+1] - voff[v]; }
+  inline const uintE* hlist(size_t e) const { return hadj + hoff[e]; }
+  inline size_t hdeg(size_t e) const { return hoff[e+1] - hoff[e]; }
+  inline void prefetch_v(size_t v) const { HKC_PF(&voff[v]); }
+  inline void prefetch_vlist(size_t v) const { HKC_PF(vadj + voff[v]); }
+  inline void prefetch_h(size_t e) const { HKC_PF(&hoff[e]); }
+};
+
+inline bool test(const word* b, size_t i) { return (b[i >> 6] >> (i & 63)) & 1; }
+inline bool test_relaxed(const word* b, size_t i) {
+  return (__atomic_load_n(&b[i >> 6], __ATOMIC_RELAXED) >> (i & 63)) & 1;
+}
+inline void set_bit(word* b, size_t i) { b[i >> 6] |= (word)1 << (i & 63); }
+
+// Growable message buffer, written only by its producer thread.
+struct MsgBuf {
+  vid* p; size_t n, cap; bool owned;
+  void grow() {
+    vid* q;
+    if (owned) q = (vid*)realloc(p, 2 * cap * sizeof(vid));
+    else { q = (vid*)malloc(2 * cap * sizeof(vid)); memcpy(q, p, n * sizeof(vid)); owned = true; }
+    p = q; cap *= 2;
+  }
+  inline void push(vid x) { if (n == cap) grow(); p[n++] = x; }
+};
+
+struct alignas(64) ThreadData { MsgBuf* dm; MsgBuf* km; word* priv; word* snap; };
+struct alignas(64) Slot { long a, b; char pad[64 - 2 * sizeof(long)]; };
+
+struct Shared {
+  vid* deg; word* status; word* dead;
+  vid* fr[2]; vid* scratch;
+  uint8_t* vown; uint8_t* hown;
+  ThreadData td[MAXT];
+  size_t nv, nh, nwv, nwh;
+  double avg_vdeg, avg_card;
+  alignas(64) long head[2];
+  alignas(64) long tail[2];
+  Slot slot[2][MAXT];
+};
+
+// Thread-local append buffer for the next frontier, flushed with one atomic.
+struct OutBuf {
+  enum { CAP = 512 };
+  vid b[CAP]; int n; long* tail; vid* dst; bool par;
+  OutBuf() : n(0) {}
+  inline void flush() {
+    if (!n) return;
+    long at;
+    if (par) at = __atomic_fetch_add(tail, (long)n, __ATOMIC_RELAXED);
+    else { at = *tail; *tail += n; }
+    memcpy(dst + at, b, sizeof(vid) * n);
+    n = 0;
+  }
+  inline void push(vid u) { b[n++] = u; if (n == CAP) flush(); }
+};
+
+// Push, in increasing order, the vertices whose status bit was set since snap.
+inline void emit_new(const word* status, const word* snap, size_t w0, size_t w1, OutBuf& ob) {
+  for (size_t w = w0; w < w1; w++) {
+    word x = status[w] & ~snap[w - w0];
+    while (x) { ob.push((vid)(w * 64 + __builtin_ctzll(x))); x &= x - 1; }
+  }
+}
+
+// Smallest degree among live vertices of words [w0, w1). Removed vertices are
+// masked to the maximum so the loop stays branch-free.
+#if defined(__x86_64__) && defined(__GNUC__) && !defined(__clang__)
+#define HKC_SIMD_CLONES __attribute__((target_clones("avx2", "default")))
+#else
+#define HKC_SIMD_CLONES
+#endif
+
+HKC_SIMD_CLONES long level_min(const vid* deg, const word* status, size_t w0, size_t w1, size_t nv) {
+  vid m = ~(vid)0;
+  for (size_t w = w0; w < w1; w++) {
+    word st = status[w];
+    if (st == ~(word)0) continue;
+    const vid* dp = deg + w * 64;
+    size_t n = nv - w * 64 < 64 ? nv - w * 64 : 64;
+    for (size_t j = 0; j < n; j++) {
+      vid x = dp[j] | ((vid)0 - (vid)((st >> j) & 1));
+      m = x < m ? x : m;
+    }
+  }
+  return m == ~(vid)0 ? LONG_MAX : (long)m;
+}
+
+// Mark live vertices of degree d as leaving (status bit) and list them in order.
+HKC_SIMD_CLONES long level_collect(const vid* deg, word* status, size_t w0, size_t w1, size_t nv, vid d, vid* out) {
+  long c = 0;
+  for (size_t w = w0; w < w1; w++) {
+    word st = status[w];
+    if (st == ~(word)0) continue;
+    const vid* dp = deg + w * 64;
+    size_t n = nv - w * 64 < 64 ? nv - w * 64 : 64;
+    word hit = 0;
+    for (size_t j = 0; j < n; j++) hit |= (word)(dp[j] == d) << j;
+    hit &= ~st;
+    status[w] = st | hit;
+    while (hit) { out[c++] = (vid)(w * 64 + __builtin_ctzll(hit)); hit &= hit - 1; }
+  }
+  return c;
+}
+
+// OR every thread's private dead marks for words [w0, w1) into the shared
+// bitmap and clear them.
+inline void merge_marks(Shared& s, size_t w0, size_t w1, int T) {
+  word* dead = s.dead;
+  for (size_t w = w0; w < w1; w++) {
+    word x = dead[w];
+    for (int t = 0; t < T; t++) { word y = s.td[t].priv[w]; if (y) { x |= y; s.td[t].priv[w] = 0; } }
+    dead[w] = x;
+  }
+}
+
+inline long clamp_chunk(long n, int T, long cap) {
+  long c = n / (8L * T);
+  return c < 1 ? 1 : (c > cap ? cap : c);
+}
+
+inline bool grab(long* head, bool par, long chunk, long limit, long& lo, long& hi) {
+  long i;
+  if (par) i = __atomic_fetch_add(head, chunk, __ATOMIC_RELAXED);
+  else { i = *head; *head += chunk; }
+  if (i >= limit) return false;
+  lo = i; hi = i + chunk < limit ? i + chunk : limit;
+  return true;
+}
+
+inline void barrier(bool par) {
+#ifdef _OPENMP
+  if (par) {
+#pragma omp barrier
+  }
+#endif
+}
+
+// Two small rings that hide the hyperedge-record and member-list misses
+// before Proc sees (members, count, frontier vertex).
+template <class Acc, class Proc>
+struct Pipe {
+  enum { D = 8 };
+  const Acc& A; Proc& P;
+  uintE e1[D]; vid v1[D]; unsigned n1, h1;
+  const uintE* m2[D]; uint32_t c2[D]; vid v2[D]; uintE e2[D]; unsigned n2, h2;
+  Pipe(const Acc& a, Proc& p) : A(a), P(p), n1(0), h1(0), n2(0), h2(0) {}
+  inline void stage2(uintE e, vid v) {
+    const uintE* M = A.hlist(e); uint32_t c = (uint32_t)A.hdeg(e);
+    HKC_PF(M);
+    if (c > 16) HKC_PF(M + 16);
+    unsigned at;
+    if (n2 == D) { P(m2[h2], c2[h2], e2[h2], v2[h2]); at = h2; h2 = (h2 + 1) % D; }
+    else { at = (h2 + n2) % D; n2++; }
+    m2[at] = M; c2[at] = c; e2[at] = e; v2[at] = v;
+  }
+  inline void add(uintE e, vid v) {
+    A.prefetch_h(e);
+    if (n1 == D) {
+      uintE oe = e1[h1]; vid ov = v1[h1];
+      e1[h1] = e; v1[h1] = v; h1 = (h1 + 1) % D;
+      stage2(oe, ov);
+    } else { unsigned at = (h1 + n1) % D; e1[at] = e; v1[at] = v; n1++; }
+  }
+  inline void drain() {
+    while (n1) { uintE oe = e1[h1]; vid ov = v1[h1]; h1 = (h1 + 1) % D; n1--; stage2(oe, ov); }
+    while (n2) { P(m2[h2], c2[h2], e2[h2], v2[h2]); h2 = (h2 + 1) % D; n2--; }
+  }
+};
+
+// Sequential push: kill directly, decrement directly.
+struct SeqProc {
+  vid* deg; word* status; long k;
+  inline void operator()(const uintE* M, uint32_t c, uintE, vid) {
+    for (uint32_t t = 0; t < c; t++) {
+      vid u = M[t];
+      long d = deg[u];
+      if (d > k) { deg[u] = (vid)--d; if (d == k) set_bit(status, u); }
+    }
+  }
+};
+
+// Parallel push: the lowest frontier member of a hyperedge kills it and sends
+// kill / decrement messages to the owners of the bitmap word / vertex.
+struct ParProc {
+  const word* status; const uint8_t* vown; const uint8_t* hown; MsgBuf* dm; MsgBuf* km;
+  inline void operator()(const uintE* M, uint32_t c, uintE e, vid v) {
+    for (uint32_t t = 0; t < c; t++) { vid w = M[t]; if (w < v && test(status, w)) return; }
+    km[hown[e >> 6]].push(e);
+    for (uint32_t t = 0; t < c; t++) { vid u = M[t]; if (!test(status, u)) dm[vown[u >> 6]].push(u); }
+  }
+};
+
+template <class Acc>
+inline long live_count(const Acc& A, const word* status, const word* dead, size_t u) {
+  const uintE* L = A.vlist(u); size_t d = A.vdeg(u);
+  long cnt = 0;
+  for (size_t j = 0; j < d; j++) {
+    uintE e = L[j];
+    if (test(dead, e)) continue;
+    const uintE* M = A.hlist(e); size_t c = A.hdeg(e);
+    size_t t = 0;
+    for (; t < c; t++) if (test_relaxed(status, M[t])) break;
+    cnt += (t == c);
+  }
+  return cnt;
+}
+
+template <class Acc>
+void worker(const Acc& A, Shared& s, int tid, int T) {
+  const bool par = T > 1;
+  vid* deg = s.deg; word* status = s.status; word* dead = s.dead;
+  const size_t nv = s.nv, nwv = s.nwv, nwh = s.nwh;
+  // Owned vertex range (64-aligned) and owned dead-bitmap words.
+  const size_t wv0 = nwv * tid / T, wv1 = nwv * (tid + 1) / T;
+  const size_t v0 = wv0 * 64;
+  const size_t wh0 = nwh * tid / T, wh1 = nwh * (tid + 1) / T;
+  ThreadData& me = s.td[tid];
+  long k = -1, remaining = (long)nv, fsize = 0;
+  int rp = 0, sp = 0;
+  bool premarked = false;  // frontier hyperedges already sit in private bitmaps
+  vid* cur = s.fr[0]; vid* nxt = s.fr[1];
+  OutBuf ob; ob.par = par;
+  while (true) {
+    if (fsize == 0) {
+      if (remaining == 0) break;
+      premarked = false;
+      // Next level: smallest live degree; its vertices form the frontier.
+      long mn = level_min(deg, status, wv0, wv1, nv);
+      s.slot[sp][tid].a = mn;
+      barrier(par);
+      long gmn = LONG_MAX;
+      for (int t = 0; t < T; t++) gmn = s.slot[sp][t].a < gmn ? s.slot[sp][t].a : gmn;
+      sp ^= 1;
+      vid* cand = s.scratch + v0;
+      long c = level_collect(deg, status, wv0, wv1, nv, (vid)gmn, cand);
+      s.slot[sp][tid].b = c;
+      barrier(par);
+      long off = 0, tot = 0;
+      for (int t = 0; t < T; t++) { if (t < tid) off += s.slot[sp][t].b; tot += s.slot[sp][t].b; }
+      sp ^= 1;
+      memcpy(cur + off, cand, sizeof(vid) * c);
+      k = gmn; fsize = tot;
+      barrier(par);
+    }
+    if (fsize == remaining) break;  // everything left peels at level k
+    const long R = remaining - fsize;
+    // Relative unit costs measured on the target machine class (pull streams
+    // incidence lists and scales better across threads than push).
+    const double push_cost = (double)fsize * (double)k * s.avg_card * (par ? HKC_W_PUSH_PAR : HKC_W_PUSH_SEQ);
+    const double pull_cost = (double)(R + (premarked ? 0 : fsize)) * s.avg_vdeg;
+    const double fix_cost = (double)R * (s.avg_vdeg + (double)k * s.avg_card) * HKC_W_FIX;
+    int mode = push_cost <= pull_cost ? 0 : 1;
+    if (fix_cost < (mode == 0 ? push_cost : pull_cost)) mode = 2;
+    const vid* F = cur;
+    long* head = &s.head[rp]; long* tail = &s.tail[rp];
+    ob.tail = tail; ob.dst = nxt;
+    long lo, hi;
+    if (premarked && mode != 1) {
+      if (mode == 2) { merge_marks(s, wh0, wh1, T); barrier(par); }
+      else memset(me.priv, 0, sizeof(word) * nwh);  // push re-kills these edges itself
+      premarked = false;
+    }
+    if (mode == 2) {
+      // Fixpoint over the remaining vertices; finishes level k.
+      long it = 0, alive = 0;
+      while (true) {
+        long changed = 0; alive = 0;
+        for (size_t w = wv0; w < wv1; w++) {
+          word live = ~__atomic_load_n(&status[w], __ATOMIC_RELAXED);
+          while (live) {
+            size_t u = w * 64 + __builtin_ctzll(live); live &= live - 1;
+            long cnt = live_count(A, status, dead, u);
+            if (cnt <= k) {
+              deg[u] = (vid)k;
+              __atomic_store_n(&status[w], status[w] | ((word)1 << (u & 63)), __ATOMIC_RELAXED);
+              changed = 1;
+            } else { deg[u] = (vid)cnt; alive++; }
+          }
+        }
+        s.slot[sp][tid].a = changed; s.slot[sp][tid].b = alive;
+        barrier(par);
+        bool any = false; long tot = 0;
+        for (int t = 0; t < T; t++) { any |= s.slot[sp][t].a != 0; tot += s.slot[sp][t].b; }
+        sp ^= 1;
+        if (!any) { alive = tot; break; }
+        it++;
+      }
+      // Survivors keep exact live degrees; mark their dead hyperedges.
+      for (size_t w = wv0; w < wv1; w++) {
+        word live = ~status[w];
+        while (live) {
+          size_t u = w * 64 + __builtin_ctzll(live); live &= live - 1;
+          const uintE* L = A.vlist(u); size_t d = A.vdeg(u);
+          for (size_t j = 0; j < d; j++) {
+            uintE e = L[j];
+            if (test_relaxed(dead, e)) continue;
+            const uintE* M = A.hlist(e); size_t c = A.hdeg(e);
+            for (size_t t = 0; t < c; t++)
+              if (test(status, M[t])) { __atomic_fetch_or(&dead[e >> 6], (word)1 << (e & 63), __ATOMIC_RELAXED); break; }
+          }
+        }
+      }
+      barrier(par);
+      remaining = alive; fsize = 0;
+      continue;
+    }
+    if (mode == 0 && !par) {
+      memcpy(me.snap, status + wv0, sizeof(word) * (wv1 - wv0));
+      SeqProc P{deg, status, k};
+      Pipe<Acc, SeqProc> pipe(A, P);
+      for (long i = 0; i < fsize && i < 8; i++) A.prefetch_v(F[i]);
+      for (long i = 0; i < fsize && i < 4; i++) A.prefetch_vlist(F[i]);
+      for (long i = 0; i < fsize; i++) {
+        if (i + 8 < fsize) A.prefetch_v(F[i + 8]);
+        if (i + 4 < fsize) A.prefetch_vlist(F[i + 4]);
+        vid v = F[i];
+        const uintE* L = A.vlist(v); size_t d = A.vdeg(v);
+        for (size_t j = 0; j < d; j++) {
+          uintE e = L[j];
+          if (test(dead, e)) continue;
+          set_bit(dead, e);
+          pipe.add(e, v);
+        }
+      }
+      pipe.drain();
+      emit_new(status, me.snap, wv0, wv1, ob);
+      ob.flush();
+    } else if (mode == 0) {
+      for (int o = 0; o < T; o++) { me.dm[o].n = 0; me.km[o].n = 0; }
+      ParProc P{status, s.vown, s.hown, me.dm, me.km};
+      Pipe<Acc, ParProc> pipe(A, P);
+      const long chunk = clamp_chunk(fsize, T, 64);
+      while (grab(head, par, chunk, fsize, lo, hi)) {
+        for (long i = lo; i < lo + 8 && i < hi; i++) A.prefetch_v(F[i]);
+        for (long i = lo; i < lo + 4 && i < hi; i++) A.prefetch_vlist(F[i]);
+        for (long i = lo; i < hi; i++) {
+          if (i + 8 < hi) A.prefetch_v(F[i + 8]);
+          if (i + 4 < hi) A.prefetch_vlist(F[i + 4]);
+          vid v = F[i];
+          const uintE* L = A.vlist(v); size_t d = A.vdeg(v);
+          for (size_t j = 0; j < d; j++) {
+            uintE e = L[j];
+            // (skip a repeated incidence so v cannot process e twice)
+            if (!test(dead, e) && (j == 0 || L[j - 1] != e)) pipe.add(e, v);
+          }
+        }
+      }
+      pipe.drain();
+      barrier(par);
+      if (tid == 0) { s.head[rp ^ 1] = 0; s.tail[rp ^ 1] = 0; }
+      for (int t = 0; t < T; t++) {
+        const MsgBuf& b = s.td[t].km[tid];
+        for (size_t i = 0; i < b.n; i++) set_bit(dead, b.p[i]);
+      }
+      memcpy(me.snap, status + wv0, sizeof(word) * (wv1 - wv0));
+      for (int t = 0; t < T; t++) {
+        const MsgBuf& b = s.td[t].dm[tid];
+        for (size_t i = 0; i < b.n; i++) {
+          vid u = b.p[i];
+          long d = deg[u];
+          if (d > k) { deg[u] = (vid)--d; if (d == k) set_bit(status, u); }
+        }
+      }
+      emit_new(status, me.snap, wv0, wv1, ob);
+      ob.flush();
+    } else {
+      // Pull: mark the frontier's hyperedges dead in private bitmaps (unless
+      // the previous pull round already did while recounting), merge them into
+      // the shared bitmap, then recount every remaining vertex.
+      if (!premarked) {
+        const long chunk = clamp_chunk(fsize, T, 256);
+        while (grab(head, par, chunk, fsize, lo, hi)) {
+          for (long i = lo; i < lo + 16 && i < hi; i++) A.prefetch_v(F[i]);
+          for (long i = lo; i < lo + 8 && i < hi; i++) A.prefetch_vlist(F[i]);
+          for (long i = lo; i < hi; i++) {
+            if (i + 16 < hi) A.prefetch_v(F[i + 16]);
+            if (i + 8 < hi) A.prefetch_vlist(F[i + 8]);
+            vid v = F[i];
+            const uintE* L = A.vlist(v); size_t d = A.vdeg(v);
+            for (size_t j = 0; j < d; j++) set_bit(me.priv, L[j]);
+          }
+        }
+        barrier(par);
+      }
+      merge_marks(s, wh0, wh1, T);
+      barrier(par);
+      // Every thread has read the previous round's tail by now.
+      if (tid == 0) { s.head[rp ^ 1] = 0; s.tail[rp ^ 1] = 0; }
+      word* pm = me.priv;
+      for (size_t w = wv0; w < wv1; w++) {
+        word live = ~status[w];
+        word drop = 0;
+        while (live) {
+          unsigned b = __builtin_ctzll(live); live &= live - 1;
+          size_t u = w * 64 + b;
+          const uintE* L = A.vlist(u); size_t d = A.vdeg(u);
+          long nd = 0;
+          for (size_t j = 0; j < d; j++) nd += test(dead, L[j]);
+          long c = (long)d - nd;
+          if (c <= k) {
+            deg[u] = (vid)k; drop |= (word)1 << b; ob.push((vid)u);
+            for (size_t j = 0; j < d; j++) set_bit(pm, L[j]);  // pre-mark while L is cached
+          } else deg[u] = (vid)c;
+        }
+        status[w] |= drop;
+      }
+      ob.flush();
+    }
+    barrier(par);
+    if (!par) { s.head[rp ^ 1] = 0; s.tail[rp ^ 1] = 0; }
+    long nf = s.tail[rp];
+    premarked = mode == 1 && nf > 0;
+    remaining -= fsize; fsize = nf;
+    std::swap(cur, nxt); rp ^= 1;
+  }
+}
+
+template <class Acc>
+uintE* run(const Acc& A, size_t nv, size_t nh, size_t mv, size_t mh) {
+  uintE* deg = pbbs::new_array_no_init<uintE>(nv ? nv : 1);
+  if (nv == 0) return deg;
+  int T = 1;
+#ifdef _OPENMP
+  T = omp_get_max_threads();
+  if (T > MAXT) T = MAXT;
+  if (T < 1) T = 1;
+#endif
+  Shared* sp = (Shared*)aligned_alloc(64, ((sizeof(Shared) + 63) / 64) * 64);
+  Shared& s = *sp;
+  s.deg = deg; s.nv = nv; s.nh = nh;
+  s.nwv = (nv + 63) / 64; s.nwh = (nh + 63) / 64;
+  const size_t nwv = s.nwv, nwh = s.nwh;
+  s.status = (word*)malloc(sizeof(word) * nwv);
+  s.dead = (word*)malloc(sizeof(word) * (nwh ? nwh : 1));
+  vid* fb = (vid*)malloc(sizeof(vid) * (3 * nv + 64));  // scratch + v0 stays in bounds
+  s.fr[0] = fb; s.fr[1] = fb + nv; s.scratch = fb + 2 * nv;
+  s.vown = (uint8_t*)malloc(nwv); s.hown = (uint8_t*)malloc(nwh ? nwh : 1);
+  s.head[0] = s.head[1] = 0; s.tail[0] = s.tail[1] = 0;
+  s.avg_vdeg = (double)mv / (double)nv;
+  s.avg_card = nh ? (double)mh / (double)nh : 0.0;
+  auto init_range = [&] (int tid, int TT) {
+    size_t w0 = nwv * tid / TT, w1 = nwv * (tid + 1) / TT;
+    size_t a = w0 * 64, b = w1 * 64 < nv ? w1 * 64 : nv;
+    for (size_t v = a; v < b; v++) deg[v] = (uintE)A.vdeg(v);
+    if (w1 > w0) memset(s.status + w0, 0, sizeof(word) * (w1 - w0));
+    memset(s.vown + w0, tid, w1 - w0);
+    size_t h0 = nwh * tid / TT, h1 = nwh * (tid + 1) / TT;
+    if (h1 > h0) memset(s.dead + h0, 0, sizeof(word) * (h1 - h0));
+    memset(s.hown + h0, tid, h1 - h0);
+  };
+  auto finish_init = [&] () {
+    if (nv & 63) s.status[nwv - 1] |= ~(word)0 << (nv & 63);  // padding bits count as removed
+  };
+  char* pool = NULL;
+  size_t per_thread = 0, DCAP = 0, KCAP = 0;
+  if (T > 1) {
+    // Initial message capacity per (producer, owner) pair; buffers grow on demand.
+    DCAP = T <= 8 ? 32768 : (262144 / T > 1024 ? 262144 / T : 1024);
+    KCAP = DCAP / 8;
+    per_thread = ((2 * T * sizeof(MsgBuf) + (size_t)T * (DCAP + KCAP) * sizeof(vid)
+                                + sizeof(word) * (nwh + nwv + 2)) + 63) / 64 * 64;
+    pool = (char*)aligned_alloc(64, per_thread * T);
+    if (pool == NULL) T = 1;  // fall back to the sequential path
+  }
+  if (T == 1) {
+    init_range(0, 1); finish_init();
+    s.td[0].snap = (word*)malloc(sizeof(word) * nwv);
+    s.td[0].priv = (word*)calloc(nwh ? nwh : 1, sizeof(word));
+    worker(A, s, 0, 1);
+    free(s.td[0].snap); free(s.td[0].priv);
+  } else {
+#ifdef _OPENMP
+#pragma omp parallel num_threads(T)
+    {
+      int tid = omp_get_thread_num(), TT = omp_get_num_threads();
+      init_range(tid, TT);
+      ThreadData& me = s.td[tid];
+      // Carve this thread's buffers out of the pool (allocated by the master
+      // thread; realloc keeps grown buffers in the master arena too).
+      char* base = pool + (size_t)tid * per_thread;
+      me.dm = (MsgBuf*)base; me.km = me.dm + TT;
+      vid* mb = (vid*)(me.km + TT);
+      for (int o = 0; o < TT; o++) { me.dm[o].p = mb; me.dm[o].n = 0; me.dm[o].cap = DCAP; me.dm[o].owned = false; mb += DCAP; }
+      for (int o = 0; o < TT; o++) { me.km[o].p = mb; me.km[o].n = 0; me.km[o].cap = KCAP; me.km[o].owned = false; mb += KCAP; }
+      me.priv = (word*)mb;
+      memset(me.priv, 0, sizeof(word) * nwh);
+      me.snap = me.priv + nwh;
+#pragma omp barrier
+      if (tid == 0) finish_init();
+#pragma omp barrier
+      worker(A, s, tid, TT);
+#pragma omp barrier
+      for (int o = 0; o < TT; o++) { if (me.dm[o].owned) free(me.dm[o].p); if (me.km[o].owned) free(me.km[o].p); }
+    }
+    free(pool);
+#endif
+  }
+  free(s.status); free(s.dead); free(fb); free(s.vown); free(s.hown); free(sp);
+  return deg;
+}
+
+// Decode arbitrary (e.g. compressed) vertex types into CSR, then peel.
+template <class vertex>
+uintE* run_generic(hypergraph<vertex>& GA) {
+  const size_t nv = GA.nv, nh = GA.nh;
+  uintT* voff = newA(uintT, nv + 1); uintT* hoff = newA(uintT, nh + 1);
+  voff[0] = 0; for (size_t v = 0; v < nv; v++) voff[v+1] = voff[v] + GA.V[v].getOutDegree();
+  hoff[0] = 0; for (size_t e = 0; e < nh; e++) hoff[e+1] = hoff[e] + GA.H[e].getOutDegree();
+  uintE* vadj = newA(uintE, voff[nv] + 1); uintE* hadj = newA(uintE, hoff[nh] + 1);
+  auto map_f = [] (const uintE& i, const uintE& j) { return pbbs::empty(); };
+  {
+    auto gen = [&] (const uintE& ngh, const uintE& offset, const Maybe<pbbs::empty>& val = Maybe<pbbs::empty>()) { vadj[offset] = ngh; };
+    for (size_t v = 0; v < nv; v++) GA.V[v].template copyOutNgh<pbbs::empty>(v, voff[v], map_f, gen);
+  }
+  {
+    auto gen = [&] (const uintE& ngh, const uintE& offset, const Maybe<pbbs::empty>& val = Maybe<pbbs::empty>()) { hadj[offset] = ngh; };
+    for (size_t e = 0; e < nh; e++) GA.H[e].template copyOutNgh<pbbs::empty>(e, hoff[e], map_f, gen);
+  }
+  CSRAccess A{voff, vadj, hoff, hadj};
+  uintE* r = run(A, nv, nh, voff[nv], hoff[nh]);
+  free(voff); free(hoff); free(vadj); free(hadj);
+  return r;
+}
+
+template <class vertex>
+uintE* dispatch(hypergraph<vertex>& GA, std::true_type) {
+  VertexAccess<vertex> A{GA.V, GA.H};
+  return run(A, GA.nv, GA.nh, GA.mv, GA.mh);
+}
+template <class vertex>
+uintE* dispatch(hypergraph<vertex>& GA, std::false_type) { return run_generic(GA); }
+
+template <class vertex>
+uintE* core_numbers(hypergraph<vertex>& GA) {
+  typedef decltype(std::declval<vertex&>().getOutNeighbors()) nbr_t;
+  return dispatch(GA, std::integral_constant<bool, std::is_same<nbr_t, uintE*>::value>());
+}
